export function createPersonnelViews({api,h,showPanel,localTime}){
 async function history(id,offset=0){await showPanel('成员资料变更历史',async signal=>{const v=await api.employmentHistory(id,offset,signal);return `<div class="dialog-header"><h2>成员资料变更历史</h2><button class="icon-button" data-resource-close aria-label="关闭人员历史">×</button></div>${v.rows.map(r=>`<article class="observation"><b>${h(r.after_value.actorName||r.actorUsername||r.actor_id||'原操作者')} · ${h(localTime(r.created_at))}</b><p>入职日期：${h(r.before_value?.startDate||'未登记')} → ${h(r.after_value.startDate||'未登记')}</p><p>最后在职日：${h(r.before_value?.endDate||'未登记')} → ${h(r.after_value.endDate||'未登记')}</p>${r.after_value.note?`<p class="preserve-text">${h(r.after_value.note)}</p>`:'<p class="muted">原成员资料维护记录，保留当时登记内容。</p>'}</article>`).join('')||'<p>暂无历史记录。</p>'}<div class="pager"><button class="secondary" data-personnel-history="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-personnel-history="${h(id)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 async function reviews(month,id,offset=0){await showPanel('管理员免打卡依据历史',async signal=>{const v=await api.adminPayrollReviewHistory(month,id,offset,signal);return `<div class="dialog-header"><h2>${h(month)} · 免打卡工资依据历史</h2><button class="icon-button" data-attendance-close aria-label="关闭工资依据">×</button></div>${v.rows.map(r=>`<article class="observation"><b>第 ${r.revision} 版 · ${h(r.actor_name)} · ${h(localTime(r.created_at))}</b><p class="preserve-text">${h(r.note)}</p><p>当时在职期间：${h(r.source_snapshot.member.startDate)} 至 ${h(r.source_snapshot.member.endDate||'未登记结束日')}</p></article>`).join('')||'<p>尚无核对依据。</p>'}<div class="pager"><button class="secondary" data-admin-review-history="${h(month)}" data-member="${h(id)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${v.total} 条</span><button class="secondary" data-admin-review-history="${h(month)}" data-member="${h(id)}" data-offset="${offset+50}" ${offset+50>=v.total?'disabled':''}>下一页</button></div>`;});}
 document.addEventListener('click',e=>{const a=e.target.closest('[data-personnel-history]'),b=e.target.closest('[data-admin-review-history]');if(a)history(a.dataset.personnelHistory,Number(a.dataset.offset||0));if(b)reviews(b.dataset.adminReviewHistory,b.dataset.member,Number(b.dataset.offset||0));});
}
